func extractStakeForDataList() ([]common.Address, [][]byte) {

	addrs := make([]common.Address, 0)
	datas := make([][]byte, 0)

	for addr, data := range getStakeForDataCache() {
		addrs = append(addrs, addr)
		datas = append(datas, data.StakeData)
	}
	return addrs, datas
}

