func extractAddStakeDataList() ([]common.Address, [][]byte) {
	addrs := make([]common.Address, 0)
	datas := make([][]byte, 0)

	for addr, data := range getAddStakeDataCache() {
		addrs = append(addrs, addr)
		datas = append(datas, data.AddStakeData)
	}
	return addrs, datas
}

